effect.shader:
const float PI = 3.14159265;
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

void main() {
    vec4 o = texture(inputImg, acScreenNorm);
    if (comprimento <= 0.0 || strength <= 0.0) { fragColor = o; return; }

    float a = angle * PI / 180.0;
    vec2 d = vec2(cos(a), sin(a));
    d.x /= max(acAspect, 1e-4);

    int n = clamp(int(samples), 4, 64);
    vec3 soma = vec3(0.0);
    float pesoTot = 0.0;
    for (int i = -64; i <= 64; i++) {
        if (i < -n || i > n) continue;
        float t = float(i) / float(n);
        float w = (1.0 - abs(t));
        vec4 c = texture(inputImg, acScreenNorm + d * comprimento * t);
        float luz = dot(c.rgb, LUMA);
        float k = smoothstep(threshold, threshold + 0.2, luz);
        soma += c.rgb * k * w;
        pesoTot += w;
    }
    vec3 streak = (soma / max(pesoTot, 1e-4)) * vec3(tintR, tintG, tintB) * strength;
    fragColor = vec4(o.rgb + streak * o.a, o.a);
}
